	@Test
	void anObservationReportsOnceWhatItsPullsTook() {
		LmdbNativeAdvisoryLearner learner = new LmdbNativeAdvisoryLearner(null);
		for (int run = 0; run < LmdbNativeAdvisoryLearner.MINIMUM_SAMPLES; run++) {
			LmdbNativeCostObservation observation = new LmdbNativeCostObservation(learner, KEY, 200D);
			observation.opened(600L);
			observation.completed();
			observation.completed();
		}

		assertThat(learner.narrow(KEY, LmdbNativeWork.between(100D, 1000D), 200D).expectedNanos())
				.as("eight runs exactly reach the minimum, a double report would have reached it after four")
				.isGreaterThan(200D);
		LmdbNativeAdvisoryLearner unfinished = new LmdbNativeAdvisoryLearner(null);
		for (int run = 0; run < 100; run++) {
			new LmdbNativeCostObservation(unfinished, KEY, 200D).opened(600L);
		}
		assertThat(unfinished.narrow(KEY, LmdbNativeWork.between(100D, 1000D), 200D).expectedNanos())
				.as("a run that never completed teaches nothing")
				.isEqualTo(200D);
	}

	private static LmdbNativeCandidate<Object> candidate(String id, double low, double high) {
		return LmdbNativeCandidate.of(id, LmdbNativeCostQuote.ofWork(LmdbNativeWork.between(low, high), 10D),
				() -> null);
	}

	private static LmdbNativeStaticPrior unitPrior() {
		double[] coefficients = new double[LmdbNativeCostVector.Feature.values().length];
		Arrays.fill(coefficients, 1D);
		return new LmdbNativeStaticPrior(coefficients);
	}

	@Test
	void aMeasuredPriceChangesTheRankingInsideTheBands() {
		LmdbNativeAdvisoryLearner learner = new LmdbNativeAdvisoryLearner(null);
		LmdbNativeAdvisoryLearner.Scope scope = learner.scope(1L, LmdbNativeAccessFacts.Source.LMDB, 0);
		List<LmdbNativeCandidate<Object>> candidates = List.of(candidate("cheap", 100D, 3000D),
				candidate("dear", 1000D, 3000D));
		LmdbNativeSelector.Ranking cold = LmdbNativeSelector.rank(candidates, unitPrior(), -1D, false, scope);
		assertThat(candidates.get(cold.winner()).id()).isEqualTo("cheap");

		LmdbNativeAdvisoryLearner.Key cheap = scope.key("cheap", candidates.get(0).quote());
		observe(learner, cheap, 400, cold.expectedNanos()[0], 5D * cold.expectedNanos()[0]);
		LmdbNativeSelector.Ranking learned = LmdbNativeSelector.rank(candidates, unitPrior(), -1D, false, scope);

		assertThat(candidates.get(learned.winner()).id()).isEqualTo("dear");
		assertThat(learned.quotedExpectedNanos()[0])
				.as("observations stay anchored on the quote, not on the advice they caused")
				.isEqualTo(cold.expectedNanos()[0]);
	}

	@Test
	void aStructuralDominatorWinsAgainstALearnedBargain() {
		LmdbNativeAdvisoryLearner learner = new LmdbNativeAdvisoryLearner(null);
		LmdbNativeAdvisoryLearner.Scope scope = learner.scope(1L, LmdbNativeAccessFacts.Source.LMDB, 0);
		LmdbNativeCandidate<Object> dominated = candidate("dominated", 10D, 3000D);
		LmdbNativeCandidate<Object> dominator = candidate("dominator", 1000D, 1200D)
				.dominating(Set.of("dominated"));
		List<LmdbNativeCandidate<Object>> candidates = List.of(dominated, dominator);
		observe(learner, scope.key("dominated", dominated.quote()), 400, 1500D, 15D);

		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(candidates, unitPrior(), -1D, false, scope);

		assertThat(ranking.expectedNanos()[0]).as("the learned bargain").isLessThan(ranking.expectedNanos()[1]);
		assertThat(candidates.get(ranking.winner()).id()).isEqualTo("dominator");
		assertThat(ranking.eliminatedBy()[0]).startsWith("Structurally dominated by dominator");
	}

	@Test
	void evidenceSurvivesARestartAndNeverCrossesAnIndexGeneration(@TempDir Path directory) throws IOException {
		Path file = directory.resolve(LmdbNativeAdvisoryLearner.FILE_NAME);
		LmdbNativeAdvisoryLearner first = LmdbNativeAdvisoryLearner.load(file, 1L);
		observe(first, KEY, 100, 200D, 600D);
		first.save();
		LmdbNativeWork band = LmdbNativeWork.between(100D, 1000D);
		double learned = first.narrow(KEY, band, 200D).expectedNanos();

		LmdbNativeAdvisoryLearner sameIndexes = LmdbNativeAdvisoryLearner.load(file, 1L);
		LmdbNativeAdvisoryLearner otherIndexes = LmdbNativeAdvisoryLearner.load(file, 2L);

		assertThat(sameIndexes.narrow(KEY, band, 200D).expectedNanos()).isEqualTo(learned);
		LmdbNativeAdvisoryLearner.Key underTwo = new LmdbNativeAdvisoryLearner.Key(KEY.id(), KEY.variant(), 2L,
				KEY.accessSource(), KEY.boundMaskClass(), KEY.cardinalityBucket());
		assertThat(otherIndexes.narrow(underTwo, band, 200D).expectedNanos()).isEqualTo(200D);
		assertThat(otherIndexes.narrow(KEY, band, 200D).expectedNanos())
				.as("evidence of another generation is not even loaded")
				.isEqualTo(200D);
		try (Stream<Path> files = Files.list(directory)) {
			assertThat(files).as("no temporary file stays behind").containsExactly(file);
		}
	}

