	@Test
	void cardinalityBucketsSeparateSizes() {
		assertThat(LmdbNativeAdvisoryLearner.cardinalityBucket(Double.NaN)).isZero();
		assertThat(LmdbNativeAdvisoryLearner.cardinalityBucket(0.5D)).isZero();
		assertThat(LmdbNativeAdvisoryLearner.cardinalityBucket(1D)).isEqualTo(1);
		assertThat(LmdbNativeAdvisoryLearner.cardinalityBucket(1_000_000D))
				.isGreaterThan(LmdbNativeAdvisoryLearner.cardinalityBucket(100D));
		assertThat(LmdbNativeAdvisoryLearner.cardinalityBucket(Double.POSITIVE_INFINITY))
				.isGreaterThan(LmdbNativeAdvisoryLearner.cardinalityBucket(Double.MAX_VALUE) - 1);
	}

	private static SailRepository store(File directory) {
		SailRepository repository = new SailRepository(new LmdbStore(directory,
				new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)));
		repository.init();
		return repository;
	}

	private static void load(SailRepository repository) {
		ValueFactory vf = SimpleValueFactory.getInstance();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (int i = 0; i < 200; i++) {
				connection.add(vf.createIRI("urn:s" + i), vf.createIRI("urn:p"), vf.createIRI("urn:o" + i));
				connection.add(vf.createIRI("urn:o" + i), vf.createIRI("urn:q"), vf.createIRI("urn:x" + i));
			}
			connection.commit();
		}
	}

	private static long drain(SailRepository repository, String query) {
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			return result.stream().count();
		}
	}

	private static long samples(File directory) throws IOException {
		Path file = directory.toPath().resolve(LmdbNativeAdvisoryLearner.FILE_NAME);
		if (!Files.isRegularFile(file)) {
			return 0L;
		}
		return Files.readAllLines(file, StandardCharsets.UTF_8)
				.stream()
				.filter(line -> !line.startsWith("#"))
				.mapToLong(line -> Long.parseLong(line.split("\t")[6]))
				.sum();
	}

	@Test
	void aStoreLearnsFromCompleteRunsOnlyAndKeepsItOverARestart(@TempDir File directory) throws Exception {
		System.setProperty(LmdbNativeAdvisoryLearner.ENABLED_PROPERTY, "true");
		SailRepository repository = store(directory);
		try {
			load(repository);
			for (int run = 0; run < 5; run++) {
				assertThat(drain(repository, LIMITED)).isEqualTo(1L);
			}
		} finally {
			repository.shutDown();
		}
		assertThat(samples(directory)).as("a LIMIT that stops early is not a complete run").isZero();

		repository = store(directory);
		try {
			for (int run = 0; run < 5; run++) {
				assertThat(drain(repository, FULL_RUN)).isEqualTo(200L);
			}
		} finally {
			repository.shutDown();
		}
		assertThat(samples(directory)).isGreaterThanOrEqualTo(5L);
		long afterFirstRestart = samples(directory);

		repository = store(directory);
		try {
			assertThat(drain(repository, FULL_RUN)).isEqualTo(200L);
		} finally {
			repository.shutDown();
		}
		assertThat(samples(directory)).as("evidence accumulates across restarts").isGreaterThan(afterFirstRestart);
	}

	@Test
	void aStoreWithTheLearnerOffWritesNothing(@TempDir File directory) throws Exception {
		System.clearProperty(LmdbNativeAdvisoryLearner.ENABLED_PROPERTY);
		SailRepository repository = store(directory);
		try {
			load(repository);
			assertThat(drain(repository, FULL_RUN)).isEqualTo(200L);
		} finally {
			repository.shutDown();
		}
		assertThat(directory.toPath().resolve(LmdbNativeAdvisoryLearner.FILE_NAME)).doesNotExist();
	}
